% Established book and source dependencies supplied to the verifier.
% They are inputs to the principal P06.2 reduction, not new claims in v62.

\begin{proposition}
\label{prop:cld-psh-positive-current-verifier-extract}
On a pure-dimensional boundaryless tropical or analytic space, a locally
integrable CLD-psh function $u$ satisfies
\[
                         \dprimeddprime[u]\geq0.
\]
For a smooth $u$, the converse holds.
\end{proposition}

\begin{theorem}
\label{thm:cld-to-classical-psh-verifier-extract}
Every CLD-psh function is classically psh.
\end{theorem}

\begin{proposition}
\label{prop:classical-psh-calculus-verifier-extract}
Classically psh functions form a sheaf and a convex cone, are stable under
finite maxima and decreasing nets, scalar extension, and analytic pullback.
A real-valued $h$ is pluriharmonic when both $h$ and $-h$ are classically
psh.
\end{proposition}

\begin{theorem}
\label{thm:supplied-p061-singular-pluriharmonic-verifier-extract}
Let $K$ be a complete nontrivially valued non-Archimedean field, and let
$X$ be a good, separated, strict, boundaryless $K$-analytic space.  Every
classically pluriharmonic function $h\colon X\to\mathbb R$ is locally real
piecewise linear.
\end{theorem}

\begin{theorem}
\label{thm:p01-real-pl-positive-current-verifier-extract}
Let $K$ be a complete nontrivially valued non-Archimedean field, let $X$
be a good, separated, boundaryless, pure-dimensional, strictly
$K$-analytic space, and let $h\colon X\to\mathbf R$ be an $\mathbf R$-PL
function.  The following are equivalent:
\begin{enumerate}
\item $\dprimeddprime[h]$ is positive;
\item the residue class $L_h(x)$ is nef for every $x\in X$;
\item $h$ is semipositive in the sense of Gubler--Jell--Rabinoff.
\end{enumerate}
GJR harmonicity means that both $h$ and $-h$ are semipositive.
\end{theorem}

\begin{proposition}
\label{prop:gr-scalar-pluriharmonic-verifier-extract}
Let $L/K$ be an analytic extension field.  A function $h$ on a
$K$-analytic space is classically pluriharmonic if and only if its pullback
to the scalar extension is classically pluriharmonic.
\end{proposition}

The last proposition is Proposition~7.2(6) of Gubler--Rabinoff,
\emph{Classically psh and pluriharmonic functions on Berkovich spaces},
arXiv:2506.13548v2.

% P06.2 scalar regularization two-gate reduction, live integration.

\begin{proposition}
\label{prop:p062-scalar-regularization-two-gate}
Let $K$ be complete and nontrivially valued, let $X$ be a good,
separated, strict, boundaryless $K$-analytic space, and let
$h\colon X\to\mathbf R$ be continuous with
$\dprimeddprime[h]=0$.  Suppose that there is an analytic extension
$L/K$ such that, for the scalar-extension map
$\pi\colon X_L\to X$ and $h_L:=h\circ\pi$, the following two conditions
hold:
\begin{enumerate}
\item the current equation ascends, so that
$\dprimeddprime[h_L]=0$;
\item current positivity regularizes for the two signs of $h_L$: if
$f\in\{h_L,-h_L\}$ and $\dprimeddprime[f]\geq0$, then $f$ is CLD-psh.
\end{enumerate}
Then $h$ is classically pluriharmonic and locally $\mathbf R$-PL.  If $X$
is pure-dimensional, then $h$ is also GJR harmonic.
\end{proposition}

\begin{corollary}
\label{cor:p062-counterexample-two-gate-obstruction}
Let $K$ be complete and nontrivially valued, let $X$ be a good, separated,
strict, boundaryless $K$-analytic space, and let
$h\colon X\to\mathbf R$ be continuous with $\dprimeddprime[h]=0$.
Suppose that $h$ is not classically pluriharmonic.  For every analytic
extension $L/K$, at least one of the following failures occurs:
\begin{enumerate}
\item $\dprimeddprime[h_L]\neq0$;
\item one of $h_L$ and $-h_L$ has nonnegative Hessian current but does
not belong to the CLD-psh hierarchy.
\end{enumerate}
For $L=K$, the first alternative is impossible.  Hence every negative
answer to P06.2 furnishes, in one of the two signs of $h$, a continuous
zero-current function outside the CLD-psh hierarchy.  If $X$ is
pure-dimensional, this is a counterexample to the converse of
\Cref{prop:cld-psh-positive-current} in its stated scope.
\end{corollary}
